from pathlib import Path
import re
out=Path(__file__).parent
old=out.parent/'2026-09-17-company-associations-original'
names={'route':['Downtown Visits','Weekly Follow-ups'],'list':['Independent Cafés','Autumn Prospects']}
def members(kind):return ''.join(f'<button class="member" data-kind="{kind}"><span>{n}</span><span aria-hidden="true">›</span></button>' for n in names[kind])
def chips(kind):return ''.join(f'<button class="member chip" data-kind="{kind}"><span>{n}</span></button>' for n in names[kind])
sections=[
'<section class="feature option1"><div class="heading"><h2>Routes &amp; Lists</h2><small>4 associations</small></div><div class="chipgroup"><h3>Routes <span>2</span></h3><div class="chips">'+chips('route')+'</div></div><div class="chipgroup"><h3>Lists <span>2</span></h3><div class="chips">'+chips('list')+'</div></div></section>',
'<section class="feature option2"><div class="heading"><h2>Routes &amp; Lists</h2><small>4 associations</small></div><div class="segments" role="tablist" aria-label="Membership type"><button role="tab" id="routes-tab" aria-selected="true" aria-controls="routes-panel" data-segment="route">Routes <span>2</span></button><button role="tab" id="lists-tab" aria-selected="false" aria-controls="lists-panel" data-segment="list">Lists <span>2</span></button></div><div id="routes-panel" role="tabpanel" aria-labelledby="routes-tab" class="routepanel">'+members('route')+'</div><div id="lists-panel" role="tabpanel" aria-labelledby="lists-tab" class="listpanel" hidden>'+members('list')+'</div></section>',
'<section class="feature option3"><div class="heading"><h2>Routes &amp; Lists</h2><small>4 associations</small></div><div class="disclosures"><details><summary><span class="summaryicon">↗</span><span><strong>Routes <b>2</b></strong><small>Downtown Visits, Weekly Follow-ups</small></span><i aria-hidden="true">⌄</i></summary>'+members('route')+'</details><details><summary><span class="summaryicon">≡</span><span><strong>Lists <b>2</b></strong><small>Independent Cafés, Autumn Prospects</small></span><i aria-hidden="true">⌄</i></summary>'+members('list')+'</details></div></section>'
]
extra='''
.feature{height:auto!important}.mobile .feature{padding:16px 0 20px}.feature h3{font:var(--tt-type-subheading);margin:0 0 8px}.feature h3 span,.segments span{color:var(--tt-color-text-secondary);margin-left:4px}.mobile .feature h3{font:17px/21px 'DINCondensed-Bold'}.chips{display:flex;gap:8px;flex-wrap:wrap}.chipgroup+.chipgroup{margin-top:16px}.member.chip{width:auto;min-height:44px!important;border:1px solid var(--tt-color-border);border-radius:var(--tt-radius-sm);padding:8px 12px;background:var(--tt-color-card);font-size:14px}.segments{display:flex;background:var(--tt-color-surface-muted);padding:4px;border-radius:var(--tt-radius-sm);gap:4px;margin-bottom:8px}.segments button{width:50%;border:0;background:none;min-height:44px;color:var(--tt-color-text-muted)}.segments button[aria-selected=true]{background:var(--tt-color-card);color:var(--tt-color-primary)}.mobile .segments button{font:17px/21px 'DINCondensed-Bold'}.option2 .member{min-height:52px!important}.option2 .member:first-child{border-top:0}.disclosures{border:1px solid var(--tt-color-border);border-radius:var(--tt-radius-md);overflow:hidden}details+details{border-top:1px solid var(--tt-color-border)}summary{list-style:none;cursor:pointer;display:flex;align-items:center;gap:12px;padding:12px;min-height:64px}summary::-webkit-details-marker{display:none}summary>span:nth-child(2){flex:1;min-width:0}summary strong{display:block;font:var(--tt-type-subheading)}.mobile summary strong{font:17px/21px 'DINCondensed-Bold'}summary b{font:var(--tt-type-caption);margin-left:4px;color:var(--tt-color-text-secondary)}summary small{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--tt-color-text-secondary);font:var(--tt-type-caption);margin-top:4px}.summaryicon{background:var(--tt-color-primary-subtle);color:var(--tt-color-primary);width:32px;height:32px;border-radius:var(--tt-radius-sm);display:grid;place-items:center}summary i{color:var(--tt-color-text-secondary);font-style:normal}details[open] summary i{transform:rotate(180deg)}details .member{padding-left:56px!important}.web .option1{display:grid;grid-template-columns:1fr 1fr;gap:16px}.web .option1 .heading{grid-column:1/-1;margin:0}.web .chipgroup+.chipgroup{margin:0}.web .option2,.web .option3{padding-bottom:20px}.web .option3 .disclosures{display:grid;grid-template-columns:1fr 1fr}.web details+details{border-top:0;border-left:1px solid var(--tt-color-border)}body.embedded .review,body.embedded .foot{display:none}body.embedded .viewport{margin:0 auto}summary:focus-visible{outline:2px solid var(--tt-color-primary);outline-offset:-2px}
'''
js='''
if(new URLSearchParams(location.search).has('embed'))document.body.classList.add('embedded');
size=function(){const natural=mode==='web'?1920:440;const embedded=document.body.classList.contains('embedded');const width=Math.min(natural,innerWidth-(embedded||innerWidth<600?0:48));const scale=width/natural;const height=mode==='web'?878:(added?956+document.querySelector('.feature').getBoundingClientRect().height/(stage.getBoundingClientRect().width/natural):956);stage.style.transform='scale('+scale+')';stage.style.height=height+'px';view.style.width=width+'px';view.style.height=height*scale+'px'};
const segments=[...document.querySelectorAll('[data-segment]')];function setSegment(b){segments.forEach(t=>{t.setAttribute('aria-selected',t===b);t.tabIndex=t===b?0:-1});document.querySelector('.routepanel').hidden=b.dataset.segment!=='route';document.querySelector('.listpanel').hidden=b.dataset.segment!=='list';size()}segments.forEach((b,i)=>{b.onclick=()=>setSegment(b);b.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const t=segments[1-i];t.focus();setSegment(t)}}});document.querySelectorAll('details').forEach(d=>d.addEventListener('toggle',size));new ResizeObserver(size).observe(document.querySelector('.feature'));size();
'''
for mode in ['mobile','web']:
 for i,section in enumerate(sections,1):
  s=(old/f'{mode}.html').read_text();start=s.index('<section class="feature"');end=s.index('<div class="slice bottom">',start)
  s=s[:start]+section+s[end:];s=s.replace('</style>',extra+'</style>').replace('</script>',js+'</script>')
  s=s.replace('Original screen preserved. Only Routes &amp; Lists is added.',f'Option {i} · '+['Compact chips','Segmented list','Expandable rows'][i-1]+'. Original screen preserved.')
  (out/f'{mode}-{i}.html').write_text(s)
